# -*- coding: utf-8 -*-
"""Three 3-session series for grades 3-6 (nine activities): Hanukkah "small light", everyday courage, and "one group"."""
import re
from mk import mk
from content_tools import add_activities

A = []
AGES = (3, 6)
SERIES_HANUKKAH = 'מערך חנוכה: אור קטן — 3 מפגשים'
SERIES_COURAGE = 'אומץ בכל יום — 3 מפגשים'
SERIES_GROUP = 'קבוצה אחת — 3 מפגשים'
MINUTES = re.compile(r'\((\d+) דק׳\)')


def finish(act, series_title, part, discussion_minutes, summary_minutes):
    """adds the series field, puts minutes on the discussion and summary steps, and sets duration to the sum of all step minutes"""
    act['series'] = {'title': series_title, 'part': part, 'total': 3}
    for step in act['flow']:
        if step['label'] == 'דיון':
            step['label'] = f'דיון ({discussion_minutes} דק׳)'
        elif step['label'] == 'סיכום':
            step['label'] = f'סיכום ({summary_minutes} דק׳)'
    total = sum(int(MINUTES.search(s['label']).group(1)) for s in act['flow'] if MINUTES.search(s['label']))
    assert 40 <= total <= 50, f"{act['id']}: {total} minutes"
    act['duration'] = total
    return act


